package com.example.minicommerce.notification.api;
import com.example.minicommerce.notification.infrastructure.*;import com.example.minicommerce.shared.security.CurrentUser;import java.util.*;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/notifications")public class NotificationController{private final NotificationRepository repo;private final CurrentUser current;public NotificationController(NotificationRepository r,CurrentUser c){repo=r;current=c;}@GetMapping public List<View>list(){return repo.findTop50ByUserIdOrderByCreatedAtDesc(current.require().id()).stream().map(n->new View(n.getId(),n.getMessage(),n.isUnread(),n.getCreatedAt())).toList();}public record View(UUID id,String message,boolean unread,java.time.Instant createdAt){}}
